package br.com.admeclesial.infrastructure.persistence.pessoa; import br.com.admeclesial.domain.pessoa.MembroFamilia; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface MembroFamiliaRepository extends JpaRepository<MembroFamilia,Long>{ Optional<MembroFamilia> findByUuid(UUID uuid); java.util.List<MembroFamilia> findByFamiliaId(Long familiaId); java.util.List<MembroFamilia> findByPessoaId(Long pessoaId); boolean existsByFamiliaIdAndPessoaIdAndDataFimIsNull(Long familiaId, Long pessoaId); }